import 'dart:io';

import 'package:flutter/material.dart';
import 'package:path_provider/path_provider.dart';

import 'background_service.dart';
import 'capture_controller.dart';
import 'self_test.dart';
import 'trial_config.dart';

Future<void> main(List<String> args) async {
  WidgetsFlutterBinding.ensureInitialized();
  final roots = await _roots();
  if (args.contains('--selftest')) {
    // Desktop only: engine check without a microphone; writes trial-logs/selftest.txt and exits.
    await Directory(roots.logs).create(recursive: true);
    final reportPath = '${roots.logs}${Platform.pathSeparator}selftest.txt';
    try {
      await runSelfTest(roots.models, reportPath);
    } catch (e, st) {
      File(reportPath).writeAsStringSync('ERROR: $e\n$st\n', mode: FileMode.append, flush: true);
      exit(1);
    }
    exit(0);
  }
  runApp(TrialApp(controller: CaptureController(
    modelsRoot: roots.models,
    logsRoot: roots.logs,
    tempDir: (await getTemporaryDirectory()).path,
  )));
}

/// Android: the app's external files folder (models pushed there by tool/push_models_android.ps1, logs pulled
/// with adb). Desktop: `models/` and `trial-logs/` next to pubspec.yaml (flutter run's working directory).
Future<({String models, String logs})> _roots() async {
  final sep = Platform.pathSeparator;
  if (Platform.isAndroid) {
    final ext = (await getExternalStorageDirectory())!.path;
    return (models: '$ext${sep}models', logs: '$ext${sep}trial-logs');
  }
  final here = Directory.current.path;
  return (models: '$here${sep}models', logs: '$here${sep}trial-logs');
}

class TrialApp extends StatelessWidget {
  const TrialApp({super.key, required this.controller});

  final CaptureController controller;

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: 'FirstLog speech trial',
      theme: ThemeData(colorSchemeSeed: Colors.red, useMaterial3: true),
      darkTheme: ThemeData(colorSchemeSeed: Colors.red, brightness: Brightness.dark, useMaterial3: true),
      home: TrialScreen(controller: controller),
    );
  }
}

class TrialScreen extends StatefulWidget {
  const TrialScreen({super.key, required this.controller});

  final CaptureController controller;

  @override
  State<TrialScreen> createState() => _TrialScreenState();
}

class _TrialScreenState extends State<TrialScreen> {
  CaptureController get c => widget.controller;

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addPostFrameCallback((_) => BackgroundService.prepare());
  }

  String _status() {
    if (c.speaking) return 'Speaking…';
    return switch (c.phase) {
      Phase.stopped => 'Stopped',
      Phase.loading => 'Loading models…',
      Phase.askingSession => 'Waiting for "new" or "continuing"',
      Phase.listening => 'Listening for key phrases',
      Phase.dictating => 'CAPTURING dictation - say the end phrase',
    };
  }

  @override
  Widget build(BuildContext context) {
    return ListenableBuilder(
      listenable: c,
      builder: (context, _) {
        final running = c.phase != Phase.stopped;
        final theme = Theme.of(context);
        return Scaffold(
          appBar: AppBar(title: const Text('FirstLog speech trial (N1)')),
          body: ListView(
            padding: const EdgeInsets.all(16),
            children: [
              Row(children: [
                const Text('Language: '),
                SegmentedButton<TrialLanguage>(
                  segments: const [
                    ButtonSegment(value: TrialLanguage.en, label: Text('EN')),
                    ButtonSegment(value: TrialLanguage.fr, label: Text('FR')),
                  ],
                  selected: {c.language},
                  onSelectionChanged: running ? null : (s) => setState(() => c.language = s.first),
                ),
              ]),
              SwitchListTile(
                contentPadding: EdgeInsets.zero,
                title: const Text('Also transcribe with Canary (set-up B)'),
                value: c.useCanary,
                onChanged: running ? null : (v) => setState(() => c.useCanary = v),
              ),
              const SizedBox(height: 8),
              SizedBox(
                height: 64,
                child: FilledButton(
                  onPressed: c.phase == Phase.loading ? null : (running ? c.stop : c.start),
                  child: Text(running ? 'Stop trial' : 'Start trial', style: const TextStyle(fontSize: 22)),
                ),
              ),
              if (c.phase == Phase.dictating) ...[
                const SizedBox(height: 8),
                SizedBox(
                  height: 56,
                  child: OutlinedButton(onPressed: c.stopDictationTap, child: const Text('Stop dictation')),
                ),
              ],
              const SizedBox(height: 16),
              Card(
                color: c.phase == Phase.dictating ? theme.colorScheme.errorContainer : null,
                child: Padding(
                  padding: const EdgeInsets.all(12),
                  child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                    Text(_status(), style: theme.textTheme.titleMedium),
                    const SizedBox(height: 4),
                    if (running) ...[
                      Text('Microphone level', style: theme.textTheme.labelSmall),
                      LinearProgressIndicator(value: (c.micLevel * 3).clamp(0.0, 1.0), minHeight: 8),
                      const SizedBox(height: 4),
                    ],
                    Text(c.partial.isEmpty ? '…' : c.partial, style: theme.textTheme.bodyLarge),
                  ]),
                ),
              ),
              if (c.error != null)
                Text('Error: ${c.error}', style: TextStyle(color: theme.colorScheme.error)),
              const SizedBox(height: 16),
              Text('Saved dictations', style: theme.textTheme.titleMedium),
              for (final d in c.dictations.reversed)
                Card(
                  child: Padding(
                    padding: const EdgeInsets.all(12),
                    child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                      Text('${d.field.name} · ended by ${d.endReason}', style: theme.textTheme.labelLarge),
                      Text('A: ${d.textA}'),
                      if (d.textB != null) Text('B: ${d.textB}  (${d.canaryMs} ms)'),
                    ]),
                  ),
                ),
              const SizedBox(height: 16),
              Text('Log', style: theme.textTheme.titleMedium),
              if (c.log != null) SelectableText(c.log!.runDir, style: theme.textTheme.bodySmall),
              for (final line in (c.log?.tail ?? const <String>[]).reversed)
                Text(line, style: const TextStyle(fontFamily: 'monospace', fontSize: 11)),
            ],
          ),
        );
      },
    );
  }
}
